"""
BaseRepository — shared SQLite CRUD scaffolding for concrete repositories.

Each repository is constructed with a ``db_provider`` callable (rather than
a live connection) so that callers can swap the underlying database — as the
test suite does by reassigning ``app.DATABASE`` — without repositories
holding on to a stale connection or path.
"""

from abc import ABC, abstractmethod


class BaseRepository(ABC):
    def __init__(self, db_provider):
        self.db_provider = db_provider

    def _fetch_one(self, query: str, params: tuple = ()) -> dict | None:
        with self.db_provider() as conn:
            row = conn.execute(query, params).fetchone()
            return dict(row) if row else None

    def _fetch_all(self, query: str, params: tuple = ()) -> list[dict]:
        with self.db_provider() as conn:
            rows = conn.execute(query, params).fetchall()
            return [dict(r) for r in rows]

    def _execute(self, query: str, params: tuple = ()):
        with self.db_provider() as conn:
            cursor = conn.execute(query, params)
            conn.commit()
            return cursor

    @abstractmethod
    def get_by_id(self, *args, **kwargs):
        """Fetch a single record by its primary key."""

    @abstractmethod
    def create(self, *args, **kwargs):
        """Insert a new record and return it as a dict."""

"""TaskRepository — all SQL for the ``tasks`` table."""

from datetime import datetime

from .base import BaseRepository


class TaskRepository(BaseRepository):
    def create(self, title: str, owner_id: int) -> dict:
        now = datetime.utcnow().isoformat()
        cursor = self._execute(
            "INSERT INTO tasks (title, status, created_at, owner_id) VALUES (?, 'pending', ?, ?)",
            (title, now, owner_id),
        )
        return {
            "id": cursor.lastrowid,
            "title": title,
            "status": "pending",
            "created_at": now,
            "owner_id": owner_id,
        }

    def get_all(self, owner_id: int) -> list[dict]:
        return self._fetch_all(
            "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC", (owner_id,)
        )

    def get_by_id(self, task_id: int, owner_id: int) -> dict | None:
        return self._fetch_one(
            "SELECT * FROM tasks WHERE id = ? AND owner_id = ?", (task_id, owner_id)
        )

    def update(
        self, task_id: int, owner_id: int, title: str | None = None, status: str | None = None
    ) -> dict | None:
        task = self.get_by_id(task_id, owner_id)
        if task is None:
            return None
        updates = []
        params = []
        if title is not None:
            updates.append("title = ?")
            params.append(title)
        if status is not None:
            updates.append("status = ?")
            params.append(status)
        if updates:
            params.append(task_id)
            params.append(owner_id)
            self._execute(
                f"UPDATE tasks SET {', '.join(updates)} WHERE id = ? AND owner_id = ?", params
            )
        return self.get_by_id(task_id, owner_id)

